class PackageAgent:
    version = "PackageAgent-v0.2"

    def __init__(
        self,
        anchor=0.12,
        rounds=5,
        close_gap=0.005,
        tracer=None,
        estimates=None,
        final_hold_s=40.0,
        meso=None,
        p_walk=0.25,
        claims=None,
        policy=None,
    ):
        self.anchor, self.rounds, self.close_gap, self.tracer = anchor, rounds, close_gap, tracer
        self.policy = policy
        self.conditional_exchange = False
        self.trades = None
        if policy:
            from .trades import TradePolicy

            self.trades = TradePolicy(policy, self._log)
        self.meso = os.environ.get("NEGOTIATOR_MESO") == "1" if meso is None else meso
        self.final_hold_s = final_hold_s
        self.p_walk = p_walk  # chance a supplier walks when its final offer is countered (D02: 2 of 9)
        self.claims = os.environ.get("NEGOTIATOR_CLAIMS") == "1" if claims is None else claims
        if policy is not None:
            self.claims = bool(policy.evidence_types)
        self.evidence = None
        if self.claims:
            from .evidence import EvidencePolicy

            self.evidence = EvidencePolicy(tracer=tracer, case_types=policy.evidence_types if policy else None)
        self.prev = {}  # supplier -> non-price terms of our last offer
        self.final_counters = {}  # supplier -> counters sent to its final offers (at most one)
        self.beat_asked = {}  # rival supplier -> final-offer sheet id we asked it to beat
        self.final_seen = {}  # final-offer sheet id -> monotonic time first seen
        if estimates is None and os.environ.get("NEGOTIATOR_ESTIMATES") != "1":
            estimates = {}  # dossier estimates are opt-in until calibrated (docs: experiments/LOG.md)
        self._estimates, self._est_case, self._est_cache = estimates, None, {}

    # -- estimates ----------------------------------------------------------------------------
    def estimates_for(self, case):
        """{supplier_id: estimate}: the injected estimates, else `dossiers.supplier_estimate`
        (with NEGOTIATOR_ESTIMATES=1)."""
        if self._estimates is not None:
            return self._estimates
        if self._est_case != case["case_id"]:
            self._est_case, self._est_cache = case["case_id"], load_estimates(case)
        return self._est_cache

    def _sup(self, case, threads, sid):
        return supplier_for(self.estimates_for(case), sid, standard_terms(threads[sid]))

    # -- helpers ------------------------------------------------------------------------------
    @staticmethod

    def _key(self, case, threads, sid):
        sheets = eligible_sheets(case, threads[sid], self._sup(case, threads, sid))
        return (len(self._ours(threads[sid])), sheets[0][0] if sheets else math.inf)

    # -- packages -----------------------------------------------------------------------------
    def _nonprice(self, case, sid, events, std, sup, cands, eligible):
        """Our non-price terms: the previous ones, unless a supplier package (by C) is cheaper
        than the supplier's own price for ours. First offer: cheapest terms at its best price.
        Values the supplier asks for that cost us nothing at the same price are adopted."""
        ref_c, _, ref_terms = cands[0]
        prev = self.prev.get(sid)
        if self.trades and case["type"] in self.policy.package_types:
            if prev is not None:
                return prev
            return self.trades.initial(case, sid, ref_terms["unit_price"], self.anchor, std, sup, reference=ref_terms)
        if prev is None:
            n = nonprice(case, best_terms(case, ref_terms["unit_price"], std, sup))
        elif not eligible:
            return prev
        else:
            n = prev
            on_prev = [c for c, _, t in cands if same_package(case, {**prev, "unit_price": 0}, t, std)]
            if on_prev and min(on_prev) > ref_c + 1e-6:
                n = nonprice(case, complete_offer(case, closing_terms(case, ref_terms, std)))
                self._log(case, "package_switch", sid, prev=prev, new=n, c_prev=min(on_prev), c_new=ref_c)
        return self._free_concessions(case, n, ref_terms, std, sup) if eligible else n

    def _free_concessions(self, case, n, theirs, std, sup):
        price = theirs["unit_price"]
        for f, v in theirs.items():
            if f == "unit_price" or f not in n or v is None or n[f] == v:
                continue
            trial = {**n, f: v}
            if not must_haves_ok(case, {**trial, "unit_price": price}, std):
                continue
            if (
                total_cost(case, {**trial, "unit_price": price}, std, sup)
                <= total_cost(case, {**n, "unit_price": price}, std, sup) + 1e-6
            ):
                n = trial
        return n

    def _ask_on(self, case, n, cands, std, sup):
        """The supplier's price for non-price terms `n`: its sheet on `n`, else the nominal price of
        its cheapest package (an unpriced combined difference) - never above the price at which `n`
        costs as much as that package."""
        on_n = [t["unit_price"] for _, _, t in cands if same_package(case, {**n, "unit_price": 0}, t, std)]
        nominal = min(on_n) if on_n else cands[0][2]["unit_price"]
        equal_c = price_for_cost(case, {**n, "unit_price": nominal}, cands[0][0], std, sup)
        return round(min(nominal, equal_c), 2)

    # -- policy -------------------------------------------------------------------------------
"""Bounded, schema-driven trades. History is authoritative across restarts."""

import itertools
import math
import time

from arena_kit.cost import complete_offer, must_haves_ok, total_cost
from arena_kit.play import moves_left

from .dossiers import build_one, load_package
from .evaluator import eligible_sheets, nonprice, price_for_cost
from .optimizer import best_terms


def packages(case, price, standard, supplier=None):
    fields = [f for f in case["negotiable"] if f != "unit_price" and case.get("term_options", {}).get(f)]
    base = complete_offer(case, {"unit_price": price})
    out = []
    for values in itertools.product(*(case["term_options"][f] for f in fields)):
        t = {**base, **dict(zip(fields, values, strict=True))}
        if must_haves_ok(case, t, standard):
            out.append((total_cost(case, t, standard, supplier), t))
    return sorted(out, key=lambda x: x[0])


def history(case, events):
    ours = [m["term_sheets"][0]["terms"] for m in events if m.get("from") == "buyer" and m.get("term_sheets")]
    keys = [nonprice(case, t) for t in ours]
    switches = sum(a != b for a, b in zip(keys, keys[1:], strict=False))
    return ours, keys, switches


class TradePolicy:
    def __init__(self, config, log):
        self.config, self.log = config, log
        self.traits = {}
        self.deadlines = {}

    def prepare(self, case):
        """Precompute dossiers before opening a session where the runner has case metadata."""
        for sid in case.get("suppliers", []):
            if sid in self.traits:
                continue
            try:
                d = build_one(load_package(), sid)
                self.traits[sid] = set(d.traits) if d else set()
            except (OSError, ValueError, KeyError, TypeError):
                self.traits[sid] = set()

    def initial(self, case, sid, price, anchor, standard, supplier, reference=None):
        self.prepare(case)
        preference = self.config.preferences.get(case["type"], self.config.preference)
        candidates = packages(case, price * (1 - anchor), standard, supplier)
        # Record both price surfaces; do not confuse buyer value with supplier willingness.
        self.log(
            case, "package_candidates", sid, at_quote=packages(case, price, standard, supplier), at_proposed=candidates
        )
        t = dict(candidates[0][1]) if candidates else best_terms(case, price, standard, supplier)
        options = case.get("term_options", {})
        if "multi_year_only" in self.traits[sid] and "contract_months" in t:
            tenors = [m for m in options.get("contract_months", []) if m >= 12 * case["buyer"]["horizon_years"]]
            if tenors:
                t["contract_months"] = max(tenors) if preference == "longer_tenor" else min(tenors)
            if "volume_per_year" in t and (reference or {}).get("volume_per_year") is not None:
                t["volume_per_year"] = reference["volume_per_year"]
        if "ppm_commitment" in t:
            # Relax only if the buyer's formula values the package equally and the must-have holds.
            for ppm in sorted(options.get("ppm_commitment", []), reverse=True):
                trial = {**t, "ppm_commitment": ppm}
                if must_haves_ok(case, trial, standard) and total_cost(case, trial, standard, supplier) <= total_cost(
                    case, t, standard, supplier
                ):
                    t = trial
                    break
        if preference == "standard_payment" and "payment_days" in t:
            if standard.get("payment_days") in options.get("payment_days", []):
                t["payment_days"] = standard["payment_days"]
        if preference == "lower_chargeback" and "chargeback_eur_per_complaint" in t:
            lower = [
                x for x in options.get("chargeback_eur_per_complaint", []) if x < t["chargeback_eur_per_complaint"]
            ]
            if lower:
                t["chargeback_eur_per_complaint"] = sorted(lower, reverse=True)[
                    min(self.config.chargeback_steps, len(lower)) - 1
                ]
                t["ppm_commitment"] = min(options["ppm_commitment"])
        return nonprice(case, t)

    def switch(self, case, sid, events, terms, standard, supplier):
        ours, tried, switches = history(case, events)
        if switches >= 2 or moves_left(case, events) < 3 or self.deadlines.get(sid, 0) - time.time() < 20:
            return terms, None
        replies = []
        for i, m in enumerate(events):
            if m.get("from") != "buyer" and m.get("term_sheets"):
                sheets = eligible_sheets(case, events[: i + 1], supplier, alternatives=True)
                if sheets:
                    replies.append(sheets[0][0])
        if len(replies) < 3 or replies[-1] < replies[-2] - 0.01 or replies[-2] < replies[-3] - 0.01:
            return terms, None
